import { useState, useRef } from "react";
import C from "../constants/colors";
import S from "../utils/storage";
import { CROPS_ALL } from "../constants/crops";
import { DISEASE_TEMPLATES, SHOPS_DATA } from "../constants/data";
import Card from "../components/ui/Card";
import Badge from "../components/ui/Badge";
import Btn from "../components/ui/Btn";

// ─── Disease list per crop (for AI prompt + smart fallback) ────────────────
const CROP_DISEASES = {
  Tomato:    ["Early Blight","Late Blight","Yellow Leaf Curl Virus","Mosaic Virus","Target Spot","Leaf Mold","Septoria Leaf Spot","Healthy"],
  Rice:      ["Blast Disease","Brown Spot","Sheath Blight","Sheath Rot","Bacterial Leaf Streak","Rice Tungro Virus","False Smut","Healthy"],
  Wheat:     ["Yellow Rust","Brown Rust","Alternaria Leaf Blight","Loose Smut","Powdery Mildew","Wheat Blast","Foot Rot","Healthy"],
  Maize:     ["Turcicum Leaf Blight","Gray Leaf Spot","Bacterial Stalk Rot","Fusarium Rot","Common Smut","Brown Spot","Maize Dwarf Mosaic","Healthy"],
  Potato:    ["Late Blight","Early Blight","Black Scurf","Fusarium Dry Rot","Verticillium Wilt","Common Scab","Potato Virus Y","Healthy"],
  Banana:    ["Sigatoka Leaf Spot","Panama Disease","Black Sigatoka","Banana Bunchy Top","Bract Mosaic Virus","Anthracnose","Erwinia Rot","Healthy"],
  Sugarcane: ["Red Rot","Whip Smut","Pokkah Boeng","Pineapple Disease","Gummosis","Grassy Shoot","Mosaic Virus","Healthy"],
  Okra:      ["Yellow Vein Mosaic Virus","Enation Leaf Curl","Damping-off","Charcoal Rot","Anthracnose","Cercospora Leaf Spot","Fusarium Wilt","Healthy"],
  Brinjal:   ["Bacterial Wilt","Shoot and Fruit Borer","Phomopsis Blight","Cercospora Leaf Spot","Damping-off","Fruit Rot","Little Leaf of Brinjal","Healthy"],
  Cotton:    ["Bacterial Blight","Cotton Leaf Curl","Fusarium Wilt","Verticillium Wilt","Areolate Mildew","Root-knot Nematode","Seedling Disease Complex","Healthy"],
  Onion:     ["Purple Blotch","Downy Mildew","Twister Disease","White Rot","Pink Root","Bacterial Soft Rot","Onion Yellow Dwarf","Healthy"],
  Groundnut: ["Tikka Leaf Spot","Groundnut Rust","Web Blotch","Bud Necrosis","Rosette Disease","Collar Rot","Stem Rot","Healthy"],
  Turmeric:  ["Rhizome Rot","Leaf Blotch","Leaf Spot","Dry Rot","Bacterial Wilt","Leaf Blight","Root-Knot Nematodes","Healthy"],
  Mango:     ["Mango Anthracnose","Powdery Mildew","Mango Malformation","Die-back","Bacterial Canker","Sooty Mould","Red Rust","Healthy"],
  Coconut:   ["Bud Rot","Tanjore Wilt","Stem Bleeding","Root Wilt","Leaf Rot","Leaf Blight","Healthy"],
  Ragi:      ["Ragi Blast","Seedling Blight","Foot Rot","Downy Mildew","Smut","Mosaic Virus","Healthy"],
};

// ─── Key visual features per crop (for AI to look for) ────────────────────
const CROP_VISUAL_CLUES = {
  Tomato:    "Look for: brown rings on leaves (Early Blight), dark water-soaked patches (Late Blight), yellow leaf curling (TYLCV), mosaic patterns.",
  Rice:      "Look for: diamond-shaped grey spots (Blast), small brown oval spots (Brown Spot), neck rot on panicle, orange discoloration on plant.",
  Wheat:     "Look for: yellow/orange powder in stripes (Yellow Rust), orange pustules scattered (Brown Rust), white powdery coating, bleached ears (Blast).",
  Maize:     "Look for: long cigar-shaped tan lesions (Turcicum Blight), rectangular grey spots (Gray Leaf Spot), black powdery galls (Common Smut), soft stalk base.",
  Potato:    "Look for: dark water-soaked patches with white fuzzy undersides (Late Blight), concentric brown rings (Early Blight), black crusty scabs on tuber.",
  Banana:    "Look for: yellow streaks turning brown oval spots (Sigatoka), yellowing of outer leaves collar (Panama Wilt), morse-code streaks on veins (BBTV).",
  Sugarcane: "Look for: red internal stalk tissue with white patches and alcoholic smell (Red Rot), black whip from top (Smut), twisted chlorotic young leaves (Pokkah Boeng).",
  Okra:      "Look for: bright yellow vein network (YVMV), downward leaf curl with enations below (Enation Curl), dark stem base (Charcoal Rot).",
  Brinjal:   "Look for: wilting with green leaves (Bacterial Wilt), entry holes in shoots/fruits (Fruit Borer), brown sunken lesions on fruits (Phomopsis).",
  Cotton:    "Look for: angular water-soaked leaf spots (Bacterial Blight), upward curling with vein thickening (Leaf Curl Virus), white powdery on leaf underside (Areolate Mildew).",
  Onion:     "Look for: purple-brown spots with yellow halo (Purple Blotch), violet-grey fuzzy growth (Downy Mildew), twisting/curling of leaves (Twister), white fluffy base (White Rot).",
  Groundnut: "Look for: brown spots with yellow halo (Tikka Early), dark spots no halo (Tikka Late), orange rust pustules on leaf underside, black collar near soil.",
  Turmeric:  "Look for: yellowing and foul-smelling rhizome rot (Soft Rot), brown-grey leaf blotches, sudden wilting (Bacterial Wilt).",
  Mango:     "Look for: black sunken lesions on leaves/fruit (Anthracnose), white powdery coating on flowers (Powdery Mildew), malformed bunchy flower panicles, twig dieback.",
  Coconut:   "Look for: rotting spindle leaf with foul smell (Bud Rot), reddish-brown bleeding at trunk base (Stem Bleeding/Tanjore Wilt), flaccid yellowing leaflets (Root Wilt).",
  Ragi:      "Look for: grey spindle spots on leaves (Blast), brown neck causing ear to break (Neck Blast), stunted bushy yellow plant (Downy Mildew), grain replaced by black spores (Smut).",
};

// ─── Smart fallback: try disease name match first, then crop-level ─────────
const getFallback = (crop, diseaseName) => {
  // Try exact match on disease name key in templates
  if (diseaseName && DISEASE_TEMPLATES[diseaseName]) return DISEASE_TEMPLATES[diseaseName];
  // Try crop key (handles both "Tomato" and lowercase "tomato" keys)
  const cropKey = Object.keys(DISEASE_TEMPLATES).find(
    k => k.toLowerCase() === crop.toLowerCase()
  );
  return cropKey ? DISEASE_TEMPLATES[cropKey] : Object.values(DISEASE_TEMPLATES)[0];
};

function DiseaseDetection({ user }) {
  const [crop, setCrop] = useState(user.crops?.[0] || "Tomato");
  const [step, setStep] = useState("upload");
  const [progress, setProgress] = useState(0);
  const [result, setResult] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);
  const fileRef = useRef(null);

  const handleFile = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (ev) => {
      setImagePreview(ev.target.result);
      analyzeImage(ev.target.result.split(",")[1], file.type || "image/jpeg");
    };
    reader.readAsDataURL(file);
  };

  const analyzeImage = async (base64, mimeType = "image/jpeg") => {
    setStep("analyzing"); setProgress(0);
    const interval = setInterval(() => setProgress(p => {
      if (p >= 88) { clearInterval(interval); return 88; }
      return p + 3;
    }), 100);

    const diseaseList = (CROP_DISEASES[crop] || []).join(", ");
    const visualClues = CROP_VISUAL_CLUES[crop] || "";

    try {
      const res = await fetch("https://api.anthropic.com/v1/messages", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-api-key": process.env.REACT_APP_ANTHROPIC_API_KEY,
          "anthropic-dangerous-direct-browser-access": "true",
        },
        body: JSON.stringify({
          model: "claude-sonnet-4-20250514",
          max_tokens: 1200,
          messages: [{
            role: "user",
            content: [
              {
                type: "image",
                source: { type: "base64", media_type: mimeType, data: base64 }
              },
              {
                type: "text",
                text: `You are an expert plant pathologist AI. Carefully analyze this REAL image of a ${crop} plant.

VISUAL INSPECTION — Observe exactly what you see:
- Color of spots/lesions: yellow, brown, black, white, grey, purple, orange, red?
- Pattern: circular rings, angular, water-soaked, powdery coating, stripe, vein yellowing, rot, galls?
- Location: leaf blade, leaf margin, stem, fruit, base, neck, root?
- Severity: 5%, 25%, 50%, 75%+ of area affected?
- Any insects, mold growth, ooze, or unusual structures?

${visualClues}

POSSIBLE DISEASES FOR ${crop.toUpperCase()} (identify the correct one from this list):
${diseaseList}

IMPORTANT RULES:
1. Base your answer ONLY on what you see in this specific image
2. Different images must get different diagnoses — do NOT give a generic answer
3. If the plant looks healthy with no visible disease signs, answer "Healthy"
4. Give EXACT medicine names with EXACT dosages used in Tamil Nadu, India

Respond ONLY with valid JSON (no markdown, no backticks, no text before or after):
{"disease":"exact disease name from the list above","confidence":85,"severity":"High","symptoms":["exact visible symptom 1 from image","exact visible symptom 2","exact visible symptom 3"],"causes":["primary pathogen/pest name","secondary cause"],"treatment":["Medicine brand (generic name) @ exact dose per litre — repeat every X days","Second medicine option @ dose","Cultural/mechanical control step"],"prevention":["preventive step 1","preventive step 2","preventive step 3"],"medicines":["Brand name (Generic) @ dosage","Brand 2 (Generic 2)"],"organic":["organic/bio option 1","organic/bio option 2"],"sprayTime":"specific best time to spray","urgency":"treat within X days/hours","tamil_summary":"2 வரி தமிழ் சுருக்கம் — நோயின் பெயர் மற்றும் உடனடி நடவடிக்கை"}`
              }
            ]
          }]
        })
      });

      const d = await res.json();
      clearInterval(interval); setProgress(100);
      if (d.error) throw new Error(d.error.message);

      const raw = d.content?.[0]?.text || "{}";
      const parsed = JSON.parse(raw.replace(/```json|```/g, "").trim());

      // Enrich with offline template data if available
      const offline = getFallback(crop, parsed.disease);
      const enriched = {
        ...parsed,
        medicines:  parsed.medicines?.length  ? parsed.medicines  : (offline?.medicines  || []),
        organic:    parsed.organic?.length    ? parsed.organic    : (offline?.organic    || []),
        sprayTime:  parsed.sprayTime          || offline?.sprayTime || "Early morning 6–9 AM",
        urgency:    parsed.urgency            || offline?.urgency   || "Treat within 7 days",
      };

      setResult(enriched);

      // Save to history
      const users = S.get("users") || [];
      const idx = users.findIndex(u => u.id === user.id);
      if (idx >= 0) {
        users[idx].diseaseHistory = [
          { date: new Date().toLocaleDateString("en-IN"), crop, ...enriched },
          ...(users[idx].diseaseHistory || []).slice(0, 9)
        ];
        S.set("users", users);
        S.set("current_user", users[idx]);
      }
      setTimeout(() => setStep("result"), 400);

    } catch (err) {
      clearInterval(interval);
      console.error("Disease API error:", err.message);
      // Always use crop-specific fallback — never wrong crop's disease
      const fallback = getFallback(crop, null);
      setResult({
        ...fallback,
        eng: fallback?.eng 
          || `${crop} plant disease detected. Immediate treatment required.`
      });
      setTimeout(() => setStep("result"), 400);
    }
  };

  const simulateAnalyze = () => {
    setStep("analyzing"); setProgress(0);
    const t = setInterval(() => setProgress(p => {
      if (p >= 100) {
        clearInterval(t);
        setResult(getFallback(crop, null));
        setTimeout(() => setStep("result"), 200);
      }
      return p + 4;
    }), 80);
  };

  const sevColor = { High: C.red, Medium: C.orange, Low: C.bg2, Healthy: C.bg2, Critical: C.red, None: C.bg2 };

  return (
    <div style={{ padding: 22 }}>
      <h1 style={{ fontSize: 21, fontWeight: 600, color: C.text, margin: "0 0 4px" }}>🔬 Crop Disease Detection</h1>
      <p style={{ color: C.muted, fontSize: 13, margin: "0 0 18px" }}>AI-powered vision analysis • 110+ diseases across 16 crops • Instant treatment plan</p>

      {step === "upload" && (
        <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 18 }}>
          <div>
            <Card style={{ marginBottom: 12 }}>
              <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 9 }}>1. Select Your Crop</div>
              <div style={{ display: "grid", gridTemplateColumns: "repeat(4,1fr)", gap: 6 }}>
                {CROPS_ALL.slice(0, 16).map(c => (
                  <button key={c} onClick={() => setCrop(c)}
                    style={{ padding: "7px 4px", borderRadius: 7, fontSize: 12, cursor: "pointer",
                      border: `1.5px solid ${crop === c ? C.bg2 : C.border}`,
                      background: crop === c ? C.pale : C.white,
                      color: crop === c ? C.bg2 : C.text,
                      fontWeight: crop === c ? 600 : 400, textAlign: "center" }}>{c}</button>
                ))}
              </div>
            </Card>

            {/* Disease list for selected crop */}
            <Card style={{ marginBottom: 12, background: C.pale }}>
              <div style={{ fontSize: 12, fontWeight: 600, color: C.bg2, marginBottom: 6 }}>
                🦠 Detectable diseases for {crop} ({(CROP_DISEASES[crop] || []).length - 1})
              </div>
              <div style={{ display: "flex", flexWrap: "wrap", gap: 4 }}>
                {(CROP_DISEASES[crop] || []).filter(d => d !== "Healthy").map(d => (
                  <span key={d} style={{ fontSize: 10.5, padding: "2px 7px", borderRadius: 10,
                    background: C.white, color: C.text, border: `1px solid ${C.border}` }}>{d}</span>
                ))}
              </div>
            </Card>

            <input ref={fileRef} type="file" accept="image/*" onChange={handleFile} style={{ display: "none" }} />
            <div onClick={() => fileRef.current?.click()}
              style={{ background: C.white, borderRadius: 12, padding: "28px 20px",
                border: `2px dashed ${C.border}`, textAlign: "center", cursor: "pointer" }}>
              <div style={{ fontSize: 42, marginBottom: 8 }}>📸</div>
              <div style={{ fontSize: 15, fontWeight: 500, color: C.text }}>Upload {crop} Plant Photo</div>
              <div style={{ fontSize: 12, color: C.muted, margin: "4px 0 16px" }}>
                Close-up of affected leaf/stem • JPG/PNG • Max 10MB
              </div>
              <Btn onClick={e => { e.stopPropagation(); fileRef.current?.click(); }}>📷 Upload & Analyze with AI</Btn>
            </div>
            <div style={{ textAlign: "center", marginTop: 10 }}>
              <span style={{ fontSize: 12, color: C.muted }}>No photo? </span>
              <button onClick={simulateAnalyze}
                style={{ fontSize: 12, color: C.bg2, background: "none", border: "none",
                  cursor: "pointer", textDecoration: "underline" }}>Use demo image instead</button>
            </div>
          </div>

          <Card>
            <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 10 }}>📋 How It Works</div>
            {[
              { n: "1", t: "Select crop & upload photo", d: "Take a clear close-up in daylight showing the affected area." },
              { n: "2", t: "AI visual inspection", d: `Claude AI checks colors, patterns & lesion shapes — distinguishing all ${(CROP_DISEASES[crop]||[]).length-1} ${crop} diseases.` },
              { n: "3", t: "Accurate diagnosis", d: "Disease name, confidence %, severity level — specific to what it sees." },
              { n: "4", t: "Full treatment plan", d: "Exact medicine names, dosages per litre/acre, spray timing for Tamil Nadu." },
              { n: "5", t: "Buy nearby", d: "Locate agri shops near you to buy the exact medicines." },
            ].map(s => (
              <div key={s.n} style={{ display: "flex", gap: 10, marginBottom: 12 }}>
                <div style={{ width: 26, height: 26, borderRadius: "50%", background: C.pale, color: C.bg2,
                  display: "flex", alignItems: "center", justifyContent: "center",
                  fontSize: 13, fontWeight: 700, flexShrink: 0 }}>{s.n}</div>
                <div>
                  <div style={{ fontSize: 13, fontWeight: 500, color: C.text }}>{s.t}</div>
                  <div style={{ fontSize: 12, color: C.muted, lineHeight: 1.4 }}>{s.d}</div>
                </div>
              </div>
            ))}
          </Card>
        </div>
      )}

      {step === "analyzing" && (
        <Card style={{ textAlign: "center", padding: "60px 40px" }}>
          {imagePreview && (
            <img src={imagePreview} alt="Analyzing"
              style={{ width: 160, height: 120, objectFit: "cover", borderRadius: 10, marginBottom: 18 }} />
          )}
          <div style={{ fontSize: 17, fontWeight: 500, color: C.text, marginBottom: 5 }}>
            Analyzing {crop} for diseases…
          </div>
          <div style={{ fontSize: 13, color: C.muted, marginBottom: 20 }}>
            Claude AI vision — checking colors, patterns & lesions against {(CROP_DISEASES[crop]||[]).length-1} {crop} diseases
          </div>
          <div style={{ height: 8, background: C.border, borderRadius: 4, overflow: "hidden", maxWidth: 320, margin: "0 auto" }}>
            <div style={{ height: "100%", width: `${progress}%`,
              background: `linear-gradient(90deg,${C.bg2},${C.light})`,
              borderRadius: 4, transition: "width 0.08s linear" }} />
          </div>
          <div style={{ fontSize: 12, color: C.muted, marginTop: 7 }}>
            {progress}% — {progress < 30 ? "Preprocessing image…" : progress < 55 ? "Identifying lesion patterns…" : progress < 78 ? "Matching disease signature…" : "Generating treatment plan…"}
          </div>
        </Card>
      )}

      {step === "result" && result && (
        <div>
          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 12 }}>
            <Card style={{ border: `1.5px solid ${sevColor[result.severity] || C.border}` }}>
              <div style={{ display: "flex", justifyContent: "space-between", marginBottom: 8 }}>
                <div>
                  <div style={{ fontSize: 11, color: C.muted, textTransform: "uppercase" }}>Detected • {crop}</div>
                  <div style={{ fontSize: 15, fontWeight: 600, color: C.text, marginTop: 2 }}>{result.disease}</div>
                </div>
                <Badge
                  color={sevColor[result.severity]}
                  bg={result.severity === "High" || result.severity === "Critical" ? C.redPale : result.severity === "Medium" ? C.orangePale : C.pale}>
                  {result.confidence || 88}% • {result.severity}
                </Badge>
              </div>
              {result.tamil_summary && (
                <div style={{ padding: "7px 10px", background: C.pale, borderRadius: 7,
                  fontSize: 12, color: C.bg2, lineHeight: 1.5, marginBottom: 10 }}>
                  🌿 {result.tamil_summary}
                </div>
              )}
              <div style={{ padding: "7px 10px",
                background: (result.severity === "High" || result.severity === "Critical") ? C.redPale : C.orangePale,
                borderRadius: 7, fontSize: 12,
                color: (result.severity === "High" || result.severity === "Critical") ? C.red : C.orange,
                fontWeight: 500, marginBottom: 10 }}>⏰ {result.urgency}</div>
              <div style={{ fontSize: 12, fontWeight: 600, color: C.text, marginBottom: 5 }}>Symptoms Observed:</div>
              {(result.symptoms || []).map((s, i) => (
                <div key={i} style={{ fontSize: 12, color: C.muted, paddingLeft: 10, lineHeight: 1.4, marginBottom: 2 }}>• {s}</div>
              ))}
              {(result.causes || []).length > 0 && (
                <>
                  <div style={{ fontSize: 12, fontWeight: 600, color: C.text, marginTop: 8, marginBottom: 5 }}>Causes:</div>
                  {result.causes.map((c, i) => (
                    <div key={i} style={{ fontSize: 12, color: C.muted, paddingLeft: 10, lineHeight: 1.4, marginBottom: 2 }}>• {c}</div>
                  ))}
                </>
              )}
            </Card>

            <Card>
              <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 8 }}>💊 Treatment Plan</div>
              {(result.treatment || []).map((t, i) => (
                <div key={i} style={{ display: "flex", gap: 7, marginBottom: 8 }}>
                  <div style={{ width: 5, height: 5, borderRadius: "50%", background: C.bg2, marginTop: 6, flexShrink: 0 }} />
                  <div style={{ fontSize: 12.5, color: C.text, lineHeight: 1.4 }}>{t}</div>
                </div>
              ))}
              <div style={{ fontSize: 12, fontWeight: 600, color: C.bg2, margin: "10px 0 6px" }}>💊 Medicines</div>
              {(result.medicines || []).map((m, i) => (
                <div key={i} style={{ fontSize: 12, color: C.muted, paddingLeft: 10, marginBottom: 2 }}>• {m}</div>
              ))}
              <div style={{ fontSize: 12, fontWeight: 600, color: C.bg2, margin: "10px 0 6px" }}>🌱 Organic Alternatives</div>
              {(result.organic || []).map((o, i) => (
                <div key={i} style={{ fontSize: 12, color: C.muted, paddingLeft: 10, marginBottom: 2 }}>• {o}</div>
              ))}
              <div style={{ marginTop: 10, padding: "7px 10px", background: C.pale, borderRadius: 7, fontSize: 12, color: C.text }}>
                ⏰ Best spray time: <strong>{result.sprayTime || result.bestTimeToSpray}</strong>
              </div>
            </Card>
          </div>

          <div style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14, marginBottom: 12 }}>
            <Card style={{ background: C.pale }}>
              <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 8 }}>🏪 Buy Medicines At</div>
              {SHOPS_DATA.slice(0, 3).map((s, i) => (
                <div key={i} style={{ display: "flex", justifyContent: "space-between", padding: "6px 0",
                  borderBottom: i < 2 ? `1px solid ${C.border}` : "none", fontSize: 12.5 }}>
                  <span style={{ color: C.text }}>{s.name}</span>
                  <span style={{ color: C.muted }}>{s.dist} km away</span>
                </div>
              ))}
            </Card>
            <Card>
              <div style={{ fontSize: 13, fontWeight: 600, color: C.text, marginBottom: 8 }}>✅ Prevention Tips</div>
              {(result.prevention || []).map((p, i) => (
                <div key={i} style={{ fontSize: 12, color: C.muted, paddingLeft: 10, lineHeight: 1.4, marginBottom: 4 }}>• {p}</div>
              ))}
            </Card>
          </div>

          <div style={{ display: "flex", gap: 9 }}>
            <Btn onClick={() => { setStep("upload"); setResult(null); setImagePreview(null); }}>🔄 Scan Another</Btn>
            <Btn variant="outline">📤 Share Report</Btn>
            <Btn variant="ghost">📋 Save to History</Btn>
          </div>
        </div>
      )}
    </div>
  );
}

export default DiseaseDetection;
